342	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
343	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
344		for id, c := range s.campaigns {
345			if id == excludeCampaign || c.Ended {
346				continue
347			}
348			if _, ok := c.index[deviceID]; ok {
349				return true
350			}
351		}
352		return false
353	}
354	
355	// operationID 是修复前的旧标识方案：冒号拼接。活动或设备标识含冒号时，
356	// 不同（活动, 设备）组合会拼出相同标识，仅用于兼容校验修复前保存的活动；
357	// 新活动一律使用 encodeOperationIDV2。
358	func operationID(campaignID, deviceID, stage string) string {
359		return campaignID + ":" + deviceID + ":" + stage
360	}
361	
362	// 操作标识方案编号，随活动一起持久化；缺省（旧存储）为旧方案。
363	const (
364		opIDSchemeLegacy = 0
365		opIDSchemeV2     = 1
366	)
367	
368	const opIDV2Prefix = "v2:"
369	
370	// encodeOperationIDV2 生成无歧义的操作标识：活动与设备标识用长度前缀编码，
371	// 任何非空标识（含冒号、中文等）都按原字符串精确保留，（活动, 设备, 阶段）
372	// 三元组与标识一一对应。nonce 用于避开与存储内已有标识（如旧方案标识）
373	// 偶然相同的情形。
374	func encodeOperationIDV2(nonce int, campaignID, deviceID, stage string) string {
375		return fmt.Sprintf("v2:%d:%d:%s%d:%s%s",
376			nonce, len(campaignID), campaignID, len(deviceID), deviceID, stage)
377	}
378	
379	// parseOperationIDV2 解析 v2 操作标识，还原活动、设备与阶段。
380	// 只接受规范编码（解析后原样重编码必须等于入参）。
381	func parseOperationIDV2(id string) (campaignID, deviceID, stage string, ok bool) {
382		rest, found := strings.CutPrefix(id, opIDV2Prefix)
383		if !found {
384			return "", "", "", false
385		}
386		readInt := func() (int, bool) {
387			i := strings.IndexByte(rest, ':')
388			if i <= 0 {
389				return 0, false
390			}
391			n, err := strconv.Atoi(rest[:i])
392			if err != nil || n < 0 {
393				return 0, false
394			}
395			rest = rest[i+1:]
396			return n, true
397		}
398		readStr := func(n int) (string, bool) {
399			if n <= 0 || len(rest) < n {
400				return "", false
401			}
402			s := rest[:n]
403			rest = rest[n:]
404			return s, true
405		}
406		nonce, ok1 := readInt()
407		lenC, ok2 := readInt()
408		if !ok1 || !ok2 {
409			return "", "", "", false
410		}
411		campaignID, ok1 = readStr(lenC)
412		lenD, ok2 := readInt()
413		if !ok1 || !ok2 {
414			return "", "", "", false
415		}
416		deviceID, ok1 = readStr(lenD)
417		if !ok1 {
418			return "", "", "", false
419		}
420		stage = rest
421		if !validStage(stage) || encodeOperationIDV2(nonce, campaignID, deviceID, stage) != id {
422			return "", "", "", false
423		}
424		return campaignID, deviceID, stage, true
425	}
426	
427	func validStage(stage string) bool {
428		return stage == StageDownload || stage == StageInstall || stage == StageRollback
429	}
430	
431	// validV2OpID 校验标识是否是指定（活动, 设备, 阶段）的规范 v2 操作标识。
432	func validV2OpID(opID, campaignID, deviceID, stage string) bool {
433		cid, did, st, ok := parseOperationIDV2(opID)
434		return ok && cid == campaignID && did == deviceID && st == stage
435	}
436	
437	// takenOperationIDs 收集存储内全部活动（含已结束）正在使用或结果历史中
438	// 出现过的操作标识，供新活动生成标识时避开相同值。
439	func (s *Store) takenOperationIDs() map[string]bool {
440		taken := map[string]bool{}
441		for _, c := range s.campaigns {
442			for _, cd := range c.Devices {
443				taken[cd.Download.ID] = true
444				taken[cd.Install.ID] = true
445				if cd.Rollback.ID != "" {
446					taken[cd.Rollback.ID] = true
447				}
448			}
449			for _, r := range c.Results {
450				taken[r.OperationID] = true
451			}
452		}
453		return taken
454	}
455	
456	func containsString(list []string, v string) bool {
457		for _, x := range list {
458			if x == v {
459				return true
460			}
461		}
462		return false
463	}
464	
465	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
466	//
467	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
468	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
469	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion；
470	// 开启回滚的活动还会在首次领取下载时把设备当时的当前版本锁定为回滚目标，
471	// 后续普通上报不改变它。
472	// 开启回滚且安装失败已被接受后，设备领取回滚操作：首次领取同样要求设备在线
473	// 且时间位于原维护窗口 [start, end) 内（不受批次放行影响），返回的操作带锁定
474	// 目标版本；离线或窗口外保留待办。回滚已领取但未完成时再次查询返回同一标识，
475	// 且可在窗口外、截止前提交结果。
476	// 已领取但未完成的操作（下载/安装/回滚）再次查询时返回同一标识，不要求在线或位于窗口内。
477	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
478	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
479	// 活动已结束（无论因超时还是提前成功/失败结束、无论领取时间在原截止前、
480	// 恰好截止或截止后）时领取是纯拒绝：返回 ErrCampaignEnded，不推进时间基线、
481	// 不改活动结论、结束时间、设备状态与状态时间、结果历史和设备影子，也不落盘，
482	// 因此被拒绝的领取时间不会影响后续合法请求或重开存储后的倒退判断。
483	// 活动仍在执行而领取首次到达截止时间时保留原有截止处理：不派发操作，
484	// 全部未结束设备按阶段记为超时（等待或正在回滚的记回滚超时），已有终态
485	// 保持不变，以本次领取时间结束活动；此次结束时间仍参与后续倒退判断。
486	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
487		s.mu.Lock()
488		defer s.mu.Unlock()
489		if err := s.checkOpen(); err != nil {
490			return nil, err
491		}
492		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
493		if err != nil {
494			return nil, err
495		}
496		if at.IsZero() {
497			return nil, ErrInvalidTime
498		}
499		if at.Before(c.LastTime) {
500			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
501		}
502		if c.Ended {
503			// 已结束活动的领取是纯拒绝：不推进时间基线、不改状态、不落盘，
504			// 否则被拒绝的领取时间会把基线推过真正已接受的时间，
505			// 使随后本来合法的请求被误判为时间倒退。
506			return nil, ErrCampaignEnded
507		}
508		var op *Operation
509		var reject error
510		err = s.commit(func() error {
511			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
512			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
513			if !at.Before(c.Deadline) {
514				c.LastTime = at
515				s.applyTimeout(c, at)
516				reject = ErrCampaignEnded
517				return nil
518			}
519			if isTerminal(cd.Status) {
520				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
521				return nil
522			}
523			c.LastTime = at
524			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
525			if stage, claimed := pendingStage(cd); claimed {
526				op = stageOperation(c, cd, stage)
527				return nil
528			}
529			// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
530			// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
531			if cd.Status == DeviceAwaitingRollback {
532				if !s.devices[deviceID].Online {
533					return nil
534				}
535				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
536					return nil
537				}
538				cd.Rollback.Claimed = true
539				cd.Rollback.ClaimedAt = at
540				cd.Status = DeviceRollingBack
541				cd.Phase = StageRollback
542				cd.At = at
543				op = stageOperation(c, cd, StageRollback)
544				return nil
545			}
546			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
547			if !s.batchOpen(c, cd) {
548				return nil
549			}
550			if !s.devices[deviceID].Online {
551				return nil // 离线保留待办，上线后继续
552			}
553			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
554				return nil // 窗口外不派发新操作；窗口为 [start, end)
555			}
556			if !cd.Download.Claimed {
557				// 首次领取下载前再次检查当前版本。
558				current := s.devices[deviceID].Version
559				if !containsString(s.versions[c.Target].AllowedFrom, current) {
560					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
561					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
562					cd.Download.Claimed = true
563					cd.Download.ClaimedAt = at
564					cd.Download.HasResult = true
565					cd.Download.Success = false
566					cd.Download.Reason = reason
567					cd.Download.At = at
568					s.failDevice(c, cd, StageDownload, reason, at)
569					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
570					return nil
571				}
572				// 开启回滚时，把首次领取下载时设备的当前版本锁定为回滚目标；
573				// 此后普通上报不改变它，也不要求该版本另行登记为升级目标。
574				if c.RollbackOnFailure && cd.RollbackTarget == "" {
575					cd.RollbackTarget = current
576				}
577				cd.Download.Claimed = true
578				cd.Download.ClaimedAt = at
579				cd.Status = DeviceDownloading
580				cd.At = at
581				op = stageOperation(c, cd, StageDownload)
582				return nil
583			}
584			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
585			cd.Install.Claimed = true
586			cd.Install.ClaimedAt = at
587			cd.Status = DeviceInstalling
588			cd.At = at
589			op = stageOperation(c, cd, StageInstall)
590			return nil
591		})
592		if err != nil {
593			return nil, err
594		}
595		if reject != nil {
596			return nil, reject
597		}
598		return op, nil
599	}
600	
601	// stageOperation 构造某一阶段对外呈现（查询待办或领取返回）的操作描述。
602	// 同一（设备, 阶段）的描述只在这一处组装，保证查询到的待办与实际领取到的
603	// 操作信息一致：标识、活动、设备与阶段固定；仅回滚操作携带首次领取下载时
604	// 锁定的目标版本（普通上报不能改写它），下载与安装的目标版本始终为空。
605	func stageOperation(c *campaignState, cd *campaignDevice, stage string) *Operation {
606		op := &Operation{CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: stage}
607		switch stage {
608		case StageDownload:
609			op.ID = cd.Download.ID
610		case StageInstall:
611			op.ID = cd.Install.ID
612		case StageRollback:
613			op.ID = cd.Rollback.ID
614			op.TargetVersion = cd.RollbackTarget
615		}
616		return op
617	}
618	
619	// pendingStage 解析设备当前仍待完成的阶段（至多一个）及其是否已领取。
620	// 这是待办判定的唯一来源，查询与领取共用，避免同一阶段的操作信息分别维护：
621	// 已领取但尚无结果的下载/安装/回滚（claimed=true）；否则等待回滚时为尚未
622	// 领取的回滚；下载成功后为尚未领取的安装；其余非终态为尚未领取的下载。
623	// 设备已结束自己的步骤（终态）时返回空阶段。
624	func pendingStage(cd *campaignDevice) (stage string, claimed bool) {
625		switch {
626		case cd.Download.Claimed && !cd.Download.HasResult:
627			return StageDownload, true
628		case cd.Install.Claimed && !cd.Install.HasResult:
629			return StageInstall, true
630		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
631			return StageRollback, true
632		case isTerminal(cd.Status):
633			return "", false
634		case cd.Status == DeviceAwaitingRollback:
635			return StageRollback, false
636		case cd.Download.HasResult:
637			// 下载已成功、安装尚未领取（ready）。
638			return StageInstall, false
639		default:
640			return StageDownload, false
641		}
642	}
643	
644	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
645	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
646		for _, other := range c.Devices {
647			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
648				return false
649			}
650		}
651		return true
652	}
653	
654	// SubmitResult 接收设备提交的操作结果。
655	//
656	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
657	// 改用不同结果、跳过未领取阶段、提交未领取的回滚、提交其他设备的操作、
658	// 活动结束后的新结果均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
659	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
660	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
661	// 回滚成功须附带版本等于锁定回滚目标的合规上报，影子与活动在同一次持久化中更新。
662	// 开启回滚的活动中，安装失败不直接结束设备，而是保留原失败原因与时间、
663	// 令设备等待回滚；回滚失败必须给出原因，设备以回滚失败结束且影子不变。
664	// 已领取且尚未接受结果的操作在截止时刻及以后提交时，结果已经迟到，
665	// 不校验附带上报与失败原因、不接收为操作结果：若提交前活动仍在执行，
666	// 本次作为首次触发截止处理——未结束设备全部超时（等待或正在回滚的记回滚
667	// 超时），活动以本次提交时间失败结束，返回 ErrCampaignEnded，本次确实推进
668	// 的时间仍参与后续倒退判断；若活动此前已因超时结束，则只返回 ErrCampaignEnded，
669	// 是不推进时间基线、不改结束时间与设备状态的纯拒绝，因此随后不早于结束时间的
670	// 合法时间不会因这次拒绝而被判为倒退。
671	// 普通设备上报不经过本方法，也不会推进活动。
672	func (s *Store) SubmitResult(res OperationResult) error {
673		s.mu.Lock()
674		defer s.mu.Unlock()
675		if err := s.checkOpen(); err != nil {
676			return err
677		}
678		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
679		if err != nil {
680			return err
681		}
682		if res.At.IsZero() {
683			return ErrInvalidTime
684		}
685		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
686		var stage string
687		var op *opState
688		switch res.OperationID {
689		case cd.Download.ID:
690			stage, op = StageDownload, &cd.Download
691		case cd.Install.ID:
692			stage, op = StageInstall, &cd.Install
693		case cd.Rollback.ID:
694			stage, op = StageRollback, &cd.Rollback
695		default:
696			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
697		}
698		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
699		// 不推进时间基线；不同结果冲突。均不改变状态。
700		if op.HasResult {
701			if resultMatches(op, res) {
702				return nil
703			}
704			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
705		}
706		if res.At.Before(c.LastTime) {
707			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
708		}
709		if !op.Claimed {
710			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段（含未领取的回滚）。
711			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
712		}
713		// 已领取且尚未接受结果的操作在截止时刻及以后提交：结果已经迟到，
714		// 不再接收为操作结果，也不校验附带上报或失败原因。
715		if !res.At.Before(c.Deadline) {
716			if c.Ended {
717				// 活动此前已因超时结束（显式推进或更早的迟到提交触发）：
718				// 本次拒绝是纯拒绝，不推进时间基线、不改结束时间、不改设备状态，
719				// 否则随后原本合法的时间会因这次拒绝而被判为倒退。
720				return ErrCampaignEnded
721			}
722			// 活动仍在执行，本次是首次触发截止处理：未结束设备全部超时
723			// （等待/正在回滚的记回滚超时），活动以失败结束，状态时间与活动
724			// 结束时间采用本次提交时间；这次确实推进的时间仍参与后续倒退判断。
725			if err := s.commit(func() error {
726				c.LastTime = res.At
727				s.applyTimeout(c, res.At)
728				return nil
729			}); err != nil {
730				return err
731			}
732			return ErrCampaignEnded
733		}
734		if !res.Success && res.Reason == "" {
735			return ErrInvalidReason
736		}
737		// 安装/回滚成功附带的设备上报与普通 Report 共用 checkReport 的同一套
738		// 规则（必填字段、版本约束、序号过旧/重复/冲突）；这里先校验并记下判定，
739		// 实际写入在下面的同一次 commit 内与活动、历史一起完成。附带上报任何
740		// 不合规都映射为 ErrInvalidReport，不改成普通上报的错误类别。
741		var repIn reportInput
742		var repCfg json.RawMessage
743		var repVerdict reportVerdict
744		if res.Success && (stage == StageInstall || stage == StageRollback) {
745			// 安装上报版本必须等于升级目标；回滚上报版本必须等于锁定的回滚目标。
746			wantVersion := c.Target
747			if stage == StageRollback {
748				wantVersion = cd.RollbackTarget
749			}
750			repIn = reportInput{
751				DeviceID: res.DeviceID,
752				Seq:      res.Seq,
753				At:       res.At,
754				Version:  res.Version,
755				Config:   res.Config,
756			}
757			var checkErr error
758			repCfg, repVerdict, checkErr = checkReport(s.devices[res.DeviceID], repIn, wantVersion)
759			if checkErr != nil {
760				return reportAttachedError(checkErr.(errBadReport))
761			}
762		}
763		var reject error
764		err = s.commit(func() error {
765			// 到达这里时提交时间早于截止（截止时刻及以后已在提交前处理）。
766			// 一致状态下持有已领取未完成操作的设备尚未终态、活动也不会结束，
767			// 此判断仅作为防御性兜底：活动结束后的新结果拒绝且不改状态。
768			if c.Ended {
769				reject = ErrCampaignEnded
770				return nil
771			}
772			if isTerminal(cd.Status) {
773				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
774				return nil
775			}
776			c.LastTime = res.At
777			op.HasResult = true
778			op.Success = res.Success
779			op.Reason = res.Reason
780			op.At = res.At
781			if !res.Success {
782				switch {
783				case stage == StageInstall && c.RollbackOnFailure:
784					// 安装失败：保留原因和时间，设备转入等待回滚（非终态）；
785					// 同批其他设备继续，后续批次立即记为未执行，活动暂不结束。
786					s.enterRollback(c, cd, res.Reason, res.At)
787				case stage == StageRollback:
788					// 回滚失败必须给出原因：设备以回滚失败结束且影子不变。
789					s.finishRollbackFailure(c, cd, res.Reason, res.At)
790				default:
791					s.failDevice(c, cd, stage, res.Reason, res.At)
792				}
793				return nil
794			}
795			switch stage {
796			case StageDownload:
797				cd.Status = DeviceReady
798				cd.Phase = StageInstall
799				cd.Reason = ""
800				cd.At = res.At
801			case StageInstall:
802				// 安装成功：附带上报与活动同时更新、一起持久化。
803				// 同序号的完全重复上报不重新写入影子（不刷新在线状态与差异时间）。
804				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
805				op.ResultSeq = res.Seq
806				op.ResultVersion = res.Version
807				op.ResultConfig = cloneRaw(res.Config)
808				cd.Status = DeviceSucceeded
809				cd.Phase = StageInstall
810				cd.Reason = ""
811				cd.At = res.At
812			case StageRollback:
813				// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
814				// 期望配置、修订号与审计保持不变；重复上报不重新写入影子。
815				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
816				op.ResultSeq = res.Seq
817				op.ResultVersion = res.Version
818				op.ResultConfig = cloneRaw(res.Config)
819				cd.Status = DeviceRollbackSucceeded
820				cd.Phase = StageRollback
821				cd.Reason = ""
822				cd.At = res.At
823			}
824			c.Results = append(c.Results, ResultRecord{
825				DeviceID:    cd.DeviceID,
826				OperationID: op.ID,
827				Stage:       stage,
828				Success:     true,
829				Version:     op.ResultVersion,
830				At:          res.At,
831			})
832			s.settle(c, res.At)
833			return nil
834		})
835		if err != nil {
836			return err
837		}
838		return reject
839	}
840	
841	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
842	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
843	// 使活动结束后的重复提交仍然有效。
844	func resultMatches(op *opState, res OperationResult) bool {
845		if op.Success != res.Success || op.Reason != res.Reason {
846			return false
847		}
848		if op.Success && op.ResultSeq != 0 {
849			return op.ResultSeq == res.Seq &&
850				op.ResultVersion == res.Version &&
851				rawEqual(op.ResultConfig, res.Config)
852		}
853		return true
854	}
855	
856	// failureResultRecord 按统一规则组装一次已接受失败结果的结果历史条目：
857	// 对应设备、该阶段的操作标识、失败标记以及首次接受的原因与发生时间。
858	// 下载失败、安装失败与回滚失败的历史条目只在这一处生成，共同记录要求
859	// 变化时不必分别改动几种失败处理。
860	func failureResultRecord(cd *campaignDevice, stage, reason string, at time.Time) ResultRecord {
861		return ResultRecord{
862			DeviceID:    cd.DeviceID,
863			OperationID: opIDFor(cd, stage),
864			Stage:       stage,
865			Success:     false,
866			Reason:      reason,
867			At:          at,
868		}
869	}
870	
871	// recordFailureResult 落实一次已接受失败结果的共同记录规则：设备的失败原因与
872	// 发生时间、以及结果历史中恰好一条失败记录只在这一处维护。失败结果本身不更新
873	// 设备版本、在线状态或上报配置，也不修改期望配置、修订号及审计；失败后设备
874	// 走向（直接失败/等待回滚/回滚失败）、批次级联与活动是否结束仍由各调用处按
875	// 现有差异分别处理。
876	func (s *Store) recordFailureResult(c *campaignState, cd *campaignDevice, stage, reason string, at time.Time) {
877		cd.Reason = reason
878		cd.At = at
879		c.Results = append(c.Results, failureResultRecord(cd, stage, reason, at))
880	}
881	
882	// enterRollback 在开启回滚的活动中处理已接受的安装失败：
883	// 按统一规则记录原安装失败的原因与时间，令设备等待回滚（非终态）；
884	// 同批其他设备可继续，后续批次立即记为未执行，但活动暂不结束。
885	func (s *Store) enterRollback(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
886		s.recordFailureResult(c, cd, StageInstall, reason, at)
887		cd.Status = DeviceAwaitingRollback
888		cd.Phase = StageRollback
889		skipLaterBatches(c, cd, at)
890		// 不结束活动：设备进入非终态的等待回滚，活动要等其回滚结束。
891	}
892	
893	// finishRollbackFailure 处理已接受的回滚失败：必须给出原因，
894	// 按统一规则记录回滚失败后设备以回滚失败结束，影子不变
895	// （失败结果不附带、不应用上报）。
896	func (s *Store) finishRollbackFailure(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
897		s.recordFailureResult(c, cd, StageRollback, reason, at)
898		cd.Status = DeviceRollbackFailed
899		cd.Phase = StageRollback
900		s.settle(c, at)
901	}
902	
903	// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
904	func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
905		for _, other := range c.Devices {
906			if other.Batch > cd.Batch && !isTerminal(other.Status) {
907				other.Status = DeviceSkipped
908				other.Phase = pendingPhase(other)
909				other.Reason = "not executed: previous batch failed"
910				other.At = at
911			}
912		}
913	}
914	
915	// failDevice 将设备记为失败：按统一规则记录阶段、原因和时间；后续批次全部
916	// 记为未执行，本批其他设备继续。若全部设备已到终态，则活动以失败结束。
917	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
918		s.recordFailureResult(c, cd, phase, reason, at)
919		cd.Status = DeviceFailed
920		cd.Phase = phase
921		skipLaterBatches(c, cd, at)
922		s.settle(c, at)
923	}
924	
925	func opIDFor(cd *campaignDevice, phase string) string {
926		switch phase {
927		case StageInstall:
928			return cd.Install.ID
929		case StageRollback:
930			return cd.Rollback.ID
931		default:
932			return cd.Download.ID
933		}
934	}
935	
936	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
937	func pendingPhase(cd *campaignDevice) string {
938		if cd.Download.HasResult && cd.Download.Success {
939			return StageInstall
940		}
941		return StageDownload
942	}
943	
944	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
945	// 已有终态保持不变，活动记为失败并结束。等待回滚或正在回滚的设备
946	// 以回滚阶段超时结束；不改写或清空影子。
947	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
948		if c.Ended {
949			return
950		}
951		for _, cd := range c.Devices {
952			if isTerminal(cd.Status) {
953				continue
954			}
955			switch cd.Status {
956			case DeviceAwaitingRollback, DeviceRollingBack:
957				cd.Status = DeviceRollbackTimeout
958				cd.Phase = StageRollback
959			default:
960				cd.Status = DeviceTimeout
961				cd.Phase = pendingPhase(cd)
962			}
963			cd.Reason = "deadline exceeded"
964			cd.At = at
965		}
966		c.Status = CampaignFailed
967		c.Ended = true
968		c.EndedAt = at
969	}
970	
971	// campaignConclusion 按设备进度推导活动应有的结论，是活动结束判定的唯一来源：
972	// 接收设备结果后的 settle 与打开已有存储时的结论核对都使用它，保证两处规则一致。
973	// 任一设备仍处于非终态（等待下载、下载中、等待安装、安装中、等待回滚、回滚中），
974	// 活动必须继续执行（ended=false，status 为 running），不能因某台设备已经成功或
975	// 失败就结束整个活动；设备离线或维护窗口结束只是暂时无法领取新操作，不影响本判断。
976	// 全部设备到达终态时活动必须已结束，且只有每台设备都 succeeded 才能 succeeded，
977	// 其余组合（失败、超时、未执行，以及回滚成功/失败/超时——回滚成功只是恢复原版本，
978	// 不算本次升级成功）只能 failed。
979	func campaignConclusion(c *campaignState) (ended bool, status string) {
980		allSucceeded := true
981		for _, cd := range c.Devices {
982			if !isTerminal(cd.Status) {
983				return false, CampaignRunning
984			}
985			if cd.Status != DeviceSucceeded {
986				allSucceeded = false
987			}
988		}
989		if allSucceeded {
990			return true, CampaignSucceeded
991		}
992		return true, CampaignFailed
993	}
994	
995	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
996	// 即使回滚成功，设备也不是 succeeded，活动仍为失败。
997	func (s *Store) settle(c *campaignState, at time.Time) {
998		ended, status := campaignConclusion(c)
999		if !ended {
1000			return
1001		}
1002		c.Ended = true
1003		c.EndedAt = at
1004		c.Status = status
1005	}
1006	
1007	func isTerminal(status string) bool {
1008		switch status {
1009		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
1010			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
1011			return true
1012		default:
1013			return false
1014		}
1015	}
1016	
1017	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
1018	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
1019	// 未到截止时间或活动已结束时为空操作。
1020	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
1021		s.mu.Lock()
1022		defer s.mu.Unlock()
1023		if err := s.checkOpen(); err != nil {
1024			return err
1025		}
1026		c, err := s.lookupCampaign(campaignID)
1027		if err != nil {
1028			return err
1029		}
1030		if at.IsZero() {
1031			return ErrInvalidTime
1032		}
1033		if at.Before(c.LastTime) {
1034			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
1035		}
1036		if c.Ended {
1037			return nil
1038		}
1039		if at.Before(c.Deadline) {
1040			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
1041			return s.commit(func() error { c.LastTime = at; return nil })
1042		}
1043		return s.commit(func() error {
1044			c.LastTime = at
1045			s.applyTimeout(c, at)
1046			return nil
1047		})
1048	}
1049	
1050	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
1051		if campaignID == "" {
1052			return nil, ErrInvalidCampaignID
1053		}
1054		c, ok := s.campaigns[campaignID]
1055		if !ok {
1056			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
1057		}
1058		return c, nil
1059	}
1060	
1061	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
1062		c, err := s.lookupCampaign(campaignID)
1063		if err != nil {
1064			return nil, nil, err
1065		}
1066		if deviceID == "" {
1067			return nil, nil, ErrInvalidDeviceID
1068		}
1069		i, ok := c.index[deviceID]
1070		if !ok {
1071			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
1072		}
1073		return c, c.Devices[i], nil
1074	}
1075	
1076	// DeviceStatusView 是一台设备在活动中的状态快照。
1077	type DeviceStatusView struct {
1078		DeviceID string
1079		Batch    int
1080		// Status 取 Device* 状态常量，含等待回滚、正在回滚、回滚成功、
1081		// 回滚失败与回滚阶段超时。
1082		Status string
1083		// Phase 是设备当前停留或失败的阶段（download/install/rollback）。
1084		Phase string
1085		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
1086		Reason string
1087		// At 是进入当前状态的时间。
1088		At time.Time
1089		// DownloadID/InstallID/RollbackID 是各阶段操作的稳定标识。
1090		DownloadID string
1091		InstallID  string
1092		RollbackID string
1093		// RollbackTarget 是开启回滚时首次领取下载锁定的回滚目标版本；未锁定为空。
1094		RollbackTarget string
1095		// InstallFailReason/InstallFailAt 是已接受的安装失败的原因与时间，
1096		// 进入回滚后仍保留原值，便于与回滚结果分别查看。
1097		InstallFailReason string
1098		InstallFailAt     time.Time
1099		// RollbackResult 表示是否已接受回滚结果。
1100		RollbackResult bool
1101		// RollbackSuccess 表示已接受的回滚结果是否成功。
1102		RollbackSuccess bool
1103		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
1104		RollbackReason string
1105		RollbackAt     time.Time
1106	}
1107	
1108	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
1109	type BatchView struct {
1110		Index   int
1111		Devices []DeviceStatusView
1112	}
1113	
1114	// CampaignView 是分批升级活动的只读快照。
1115	type CampaignView struct {
1116		ID            string
1117		Operator      string
1118		TargetVersion string
1119		CreatedAt     time.Time
1120		BatchSize     int
1121		WindowStart   time.Time
1122		WindowEnd     time.Time
1123		Deadline      time.Time
1124		// RollbackOnFailure 表示该活动是否开启安装失败回滚。
1125		RollbackOnFailure bool
1126		// Status 取 Campaign* 状态常量。
1127		Status  string
1128		Ended   bool
1129		EndedAt time.Time
1130		// Devices 按提交次序给出每台设备的状态。
1131		Devices []DeviceStatusView
1132		// Batches 按批次号分组，保留设备提交次序。
1133		Batches []BatchView
1134		// Results 是按接受顺序排列的结果历史（重复提交不产生新记录）。
1135		Results []ResultRecord
1136	}
1137	
1138	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
1139	// 失败或超时原因及结果历史。返回数据为独立副本。
1140	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
1141		s.mu.Lock()
1142		defer s.mu.Unlock()
1143		if err := s.checkOpen(); err != nil {
1144			return CampaignView{}, err
1145		}
1146		c, err := s.lookupCampaign(campaignID)
1147		if err != nil {
1148			return CampaignView{}, err
1149		}
1150		v := CampaignView{
1151			ID:                c.ID,
1152			Operator:          c.Operator,
1153			TargetVersion:     c.Target,
1154			CreatedAt:         c.CreatedAt,
1155			BatchSize:         c.BatchSize,
1156			WindowStart:       c.WindowStart,
1157			WindowEnd:         c.WindowEnd,
1158			Deadline:          c.Deadline,
1159			RollbackOnFailure: c.RollbackOnFailure,
1160			Status:            c.Status,
1161			Ended:             c.Ended,
1162			EndedAt:           c.EndedAt,
1163			Results:           make([]ResultRecord, len(c.Results)),
1164		}
1165		copy(v.Results, c.Results)
1166		for _, cd := range c.Devices {
1167			dv := DeviceStatusView{
1168				DeviceID:       cd.DeviceID,
1169				Batch:          cd.Batch,
1170				Status:         cd.Status,
1171				Phase:          cd.Phase,
1172				Reason:         cd.Reason,
1173				At:             cd.At,
1174				DownloadID:     cd.Download.ID,
1175				InstallID:      cd.Install.ID,
1176				RollbackID:     cd.Rollback.ID,
1177				RollbackTarget: cd.RollbackTarget,
1178			}
1179			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1180			if cd.Install.HasResult && !cd.Install.Success {
1181				dv.InstallFailReason = cd.Install.Reason
1182				dv.InstallFailAt = cd.Install.At
1183			}
1184			// 回滚结果的原因与时间单独呈现。
1185			if cd.Rollback.HasResult {
1186				dv.RollbackResult = true
1187				dv.RollbackSuccess = cd.Rollback.Success
1188				dv.RollbackReason = cd.Rollback.Reason
1189				dv.RollbackAt = cd.Rollback.At
1190			}
1191			v.Devices = append(v.Devices, dv)
1192			for len(v.Batches) <= cd.Batch {
1193				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1194			}
1195			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1196		}
1197		return v, nil
1198	}
1199	
1200	// DeviceWork 是设备当前版本与待执行操作的查询结果。
1201	type DeviceWork struct {
1202		DeviceID string
1203		Version  string
1204		Online   bool
1205		// CampaignID 是设备当前所在的未结束活动；没有时为空。
1206		CampaignID string
1207		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
1208		// 等待回滚时为尚未领取的回滚操作，其 TargetVersion 给出锁定的回滚目标。
1209		Pending *Operation
1210		// PendingClaimed 表示 Pending 是否已领取（未领取的安装或回滚仍须等维护窗口）。
1211		PendingClaimed bool
1212	}
1213	
1214	// GetDeviceWork 查询设备当前版本及其待执行操作。
1215	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
1216		s.mu.Lock()
1217		defer s.mu.Unlock()
1218		if err := s.checkOpen(); err != nil {
1219			return DeviceWork{}, err
1220		}
1221		d, err := s.lookup(deviceID)
1222		if err != nil {
1223			return DeviceWork{}, err
1224		}
1225		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
1226		for id, c := range s.campaigns {
1227			if c.Ended {
1228				continue
1229			}
1230			i, ok := c.index[deviceID]
1231			if !ok {
1232				continue
1233			}
1234			cd := c.Devices[i]
1235			// 设备已结束自己的步骤但活动尚未结束时，仍保留活动标识、不再有待办；
1236			// pendingStage 是待办判定的唯一来源，stageOperation 是描述的唯一来源，
1237			// 因而这里看到的标识/目标与 Claim 实际领取到的操作完全一致。
1238			if stage, claimed := pendingStage(cd); stage != "" {
1239				w.Pending = stageOperation(c, cd, stage)
1240				w.PendingClaimed = claimed
1241			}
1242			w.CampaignID = id
1243			break
1244		}
1245		return w, nil
1246	}
1247	
1248	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
1249	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
1250		s.mu.Lock()
1251		defer s.mu.Unlock()
1252		if err := s.checkOpen(); err != nil {
1253			return nil, err
1254		}
1255		out := make([]VersionSpec, 0, len(s.versions))
1256		for _, v := range s.versions {
1257			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
1258		}
1259		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
1260		return out, nil
1261	}
