144			// 推进时间基线，使被改写的 d3 领取时间不早于基线之外的其他检查。
145			if err := s.AdvanceCampaign(spec.ID, upBase.Add(40*time.Minute)); err != nil {
146				t.Fatal(err)
147			}
148			dir := s.dir
149			s.Close()
150			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
151				d := campaignDeviceDoc(doc, spec.ID, "d3")
152				dl := d["download"].(map[string]any)
153				dl["claimed"] = true
154				dl["claimedAt"] = "2026-10-02T12:30:00Z"
155				d["status"] = DeviceDownloading
156				d["phase"] = StageDownload
157				d["at"] = "2026-10-02T12:30:00Z"
158			})
159			assertReopenCorrupt(t, dir, original)
160		})
161	
162		// 前序设备安装失败后等待回滚：即使开启了回滚，也不是“安装成功”，
163		// 后批被跳过设备若出现已领取下载记录，必须拒绝打开。
164		t.Run("predecessor awaiting rollback is not released", func(t *testing.T) {
165			s := setupUpgrade(t, "r1", "r2")
166			spec := upSpec()
167			spec.ID = "cmp-rb"
168			spec.Devices = []string{"r1", "r2"}
169			spec.BatchSize = 1
170			spec.RollbackOnFailure = true
171			createCampaign(t, s, spec)
172			bringOnline(t, s, "r1")
173			bringOnline(t, s, "r2")
174			dl, _ := s.Claim(spec.ID, "r1", upBase)
175			if err := s.SubmitResult(OperationResult{
176				CampaignID: spec.ID, DeviceID: "r1", OperationID: dl.ID,
177				At: upBase.Add(time.Minute), Success: true,
178			}); err != nil {
179				t.Fatal(err)
180			}
181			in, _ := s.Claim(spec.ID, "r1", upBase.Add(2*time.Minute))
182			if err := s.SubmitResult(OperationResult{
183				CampaignID: spec.ID, DeviceID: "r1", OperationID: in.ID,
184				At: upBase.Add(3 * time.Minute), Success: false, Reason: "install boom",
185			}); err != nil {
186				t.Fatal(err)
187			}
188			cv := mustGetCampaign(s, spec.ID)
189			if findDevice(cv, "r1").Status != DeviceAwaitingRollback ||
190				findDevice(cv, "r2").Status != DeviceSkipped {
191				t.Fatalf("precondition: %+v", cv.Devices)
192			}
193			if err := s.AdvanceCampaign(spec.ID, upBase.Add(40*time.Minute)); err != nil {
194				t.Fatal(err)
195			}
196			dir := s.dir
197			s.Close()
198			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
199				d := campaignDeviceDoc(doc, spec.ID, "r2")
200				// skipped 终态改写为“已领取下载中”，并补上首次领取下载时锁定
201				// 的回滚目标，使其单独看是一条自洽的下载中记录；矛盾只在批次
202				// 放行顺序上。
203				d["status"] = DeviceDownloading
204				d["phase"] = StageDownload
205				d["at"] = "2026-10-02T12:30:00Z"
206				d["rollbackTarget"] = "v1"
207				delete(d, "reason")
208				dl := d["download"].(map[string]any)
209				dl["claimed"] = true
210				dl["claimedAt"] = "2026-10-02T12:30:00Z"
211			})
212			assertReopenCorrupt(t, dir, original)
213		})
214	}
215	
216	// TestRestoreBatchReleaseOrderingAccepted 保护合法的批次与时间记录不被误拒。
217	func TestRestoreBatchReleaseOrderingAccepted(t *testing.T) {
218		// 题设示例的合法边界：第二批设备在 12:23（等于最后一台前序设备安装
219		// 成功时刻）首次领取下载，必须接受。
220		t.Run("claimed exactly at slowest predecessor success time", func(t *testing.T) {
221			s, dir, spec := buildBatchGateStore(t)
222			s.Close()
223			setDownloadClaimedAt(t, dir, spec.ID, "b3", "2026-10-02T12:23:00Z")
224			s2, err := Open(dir)
225			if err != nil {
226				t.Fatalf("claim at equal instant must open: %v", err)
227			}
228			defer s2.Close()
229			w, err := s2.GetDeviceWork("b3")
230			if err != nil {
231				t.Fatal(err)
232			}
233			if w.CampaignID != spec.ID || w.Pending == nil ||
234				w.Pending.Kind != StageDownload || !w.PendingClaimed {
235				t.Fatalf("b3 claimed download must be preserved: %+v", w)
236			}
237		})
238	
239		// 相同时刻的不同时区写法不能被判为乱序：20:23+08:00 即 12:23Z。
240		t.Run("equal instant with different timezone notation", func(t *testing.T) {
241			s, dir, spec := buildBatchGateStore(t)
242			s.Close()
243			setDownloadClaimedAt(t, dir, spec.ID, "b3", "2026-10-02T20:23:00+08:00")
244			s2, err := Open(dir)
245			if err != nil {
246				t.Fatalf("same instant in another timezone must open: %v", err)
247			}
248			defer s2.Close()
249			d := findDevice(mustGetCampaign(s2, spec.ID), "b3")
250			if d.Status != DeviceDownloading {
251				t.Fatalf("b3 progress lost: %+v", d)
252			}
253		})
254	
255		// 不同时区写法表示的更早时刻仍须拒绝（13:22+01:00 即 12:22Z）。
256		t.Run("earlier instant across timezone refused", func(t *testing.T) {
257			s, dir, spec := buildBatchGateStore(t)
258			s.Close()
259			original := setDownloadClaimedAt(t, dir, spec.ID, "b3", "2026-10-02T13:22:00+01:00")
260			assertReopenCorrupt(t, dir, original)
261		})
262	
263		// 正常走完全部批次的活动重开不受影响，批次顺序、终态与历史保留。
264		t.Run("legal multi batch success reopens", func(t *testing.T) {
265			s, dir, spec := buildBatchGateStore(t)
266			dl := findDevice(mustGetCampaign(s, spec.ID), "b3").DownloadID
267			if err := s.SubmitResult(OperationResult{
268				CampaignID: spec.ID, DeviceID: "b3", OperationID: dl,
269				At: upBase.Add(26 * time.Minute), Success: true,
270			}); err != nil {
271				t.Fatal(err)
272			}
273			in, _ := s.Claim(spec.ID, "b3", upBase.Add(27*time.Minute))
274			if err := s.SubmitResult(OperationResult{
275				CampaignID: spec.ID, DeviceID: "b3", OperationID: in.ID,
276				At: upBase.Add(28 * time.Minute), Success: true,
277				Seq: 2, Version: "v2", Config: json.RawMessage(`{}`),
278			}); err != nil {
279				t.Fatal(err)
280			}
281			want := mustGetCampaign(s, spec.ID)
282			s.Close()
283			s2, err := Open(dir)
284			if err != nil {
285				t.Fatalf("legal multi-batch campaign must reopen: %v", err)
286			}
287			defer s2.Close()
288			got := mustGetCampaign(s2, spec.ID)
289			if !got.Ended || got.Status != CampaignSucceeded || len(got.Results) != len(want.Results) {
290				t.Fatalf("campaign state changed: %+v", got)
291			}
292		})
293	
294		// 同批设备各自推进：一台已领取下载未完成，同批另一台随后领取，
295		// 不需要等待同批设备成功，重开必须接受。
296		t.Run("same batch devices do not gate each other", func(t *testing.T) {
297			s := setupUpgrade(t, "a1", "a2")
298			spec := upSpec()
299			spec.Devices = []string{"a1", "a2"}
300			spec.BatchSize = 2
301			createCampaign(t, s, spec)
302			bringOnline(t, s, "a1")
303			bringOnline(t, s, "a2")
304			if _, err := s.Claim(spec.ID, "a1", upBase.Add(5*time.Minute)); err != nil {
305				t.Fatal(err)
306			}
307			if _, err := s.Claim(spec.ID, "a2", upBase.Add(6*time.Minute)); err != nil {
308				t.Fatal(err)
309			}
310			dir := s.dir
311			s.Close()
312			s2, err := Open(dir)
313			if err != nil {
314				t.Fatalf("same-batch claims must reopen: %v", err)
315			}
316			defer s2.Close()
317			cv := mustGetCampaign(s2, spec.ID)
318			if findDevice(cv, "a1").Status != DeviceDownloading ||
319				findDevice(cv, "a2").Status != DeviceDownloading {
320				t.Fatalf("both downloads must remain claimed: %+v", cv.Devices)
321			}
322		})
323	
324		// 后批正常等待、尚未领取下载：前批是否成功都不能成为拒绝理由。
325		t.Run("later batch never claimed while predecessor unfinished", func(t *testing.T) {
326			s := setupUpgrade(t, "d1", "d2")
327			spec := upSpec()
328			spec.Devices = []string{"d1", "d2"}
329			spec.BatchSize = 1
330			createCampaign(t, s, spec)
331			bringOnline(t, s, "d1")
332			bringOnline(t, s, "d2")
333			// 第一批仅领取下载、未完成；第二批一直 pending。
334			if _, err := s.Claim(spec.ID, "d1", upBase.Add(5*time.Minute)); err != nil {
335				t.Fatal(err)
336			}
337			dir := s.dir
338			s.Close()
339			s2, err := Open(dir)
340			if err != nil {
341				t.Fatalf("waiting later batch must reopen: %v", err)
342			}
343			defer s2.Close()
344			cv := mustGetCampaign(s2, spec.ID)
345			if findDevice(cv, "d2").Status != DevicePending {
346				t.Fatalf("d2 must stay pending: %+v", findDevice(cv, "d2"))
347			}
348		})
349	
350		// 前批失败导致后批未执行（skipped）：后批没有下载领取时间，正常打开。
351		t.Run("later batch skipped after predecessor failure reopens", func(t *testing.T) {
352			s := setupUpgrade(t, "d1", "d2")
353			spec := upSpec()
354			spec.Devices = []string{"d1", "d2"}
355			spec.BatchSize = 1
356			createCampaign(t, s, spec)
357			bringOnline(t, s, "d1")
358			dl, _ := s.Claim(spec.ID, "d1", upBase.Add(5*time.Minute))
359			if err := s.SubmitResult(OperationResult{
360				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
361				At: upBase.Add(6 * time.Minute), Success: false, Reason: "boom",
362			}); err != nil {
363				t.Fatal(err)
364			}
365			cv0 := mustGetCampaign(s, spec.ID)
366			if !cv0.Ended || findDevice(cv0, "d2").Status != DeviceSkipped {
367				t.Fatalf("precondition: %+v", cv0)
368			}
369			dir := s.dir
370			s.Close()
371			s2, err := Open(dir)
372			if err != nil {
373				t.Fatalf("skipped later batch must reopen: %v", err)
374			}
375			defer s2.Close()
376		})
377	
378		// 尚未领取下载就随活动截止超时：没有下载领取时间，正常打开。
379		t.Run("unclaimed device times out at deadline reopens", func(t *testing.T) {
380			s := setupUpgrade(t, "d1", "d2", "d3")
381			spec := upSpec()
382			spec.Devices = []string{"d1", "d2", "d3"}
383			spec.BatchSize = 1
384			createCampaign(t, s, spec)
385			bringOnline(t, s, "d1")
386			bringOnline(t, s, "d2")
387			// d1 完成；d2 已领取下载未完成；d3 从未领取。
388			finishDevice(t, s, spec, "d1", upBase.Add(5*time.Minute))
389			if _, err := s.Claim(spec.ID, "d2", upBase.Add(10*time.Minute)); err != nil {
390				t.Fatal(err)
391			}
392			if err := s.AdvanceCampaign(spec.ID, spec.Deadline); err != nil {
393				t.Fatal(err)
394			}
395			dir := s.dir
396			s.Close()
397			s2, err := Open(dir)
398			if err != nil {
399				t.Fatalf("deadline-timeout campaign must reopen: %v", err)
400			}
401			defer s2.Close()
402			cv := mustGetCampaign(s2, spec.ID)
403			if !cv.Ended || findDevice(cv, "d2").Status != DeviceTimeout ||
404				findDevice(cv, "d3").Status != DeviceTimeout {
405				t.Fatalf("timeout states lost: %+v", cv.Devices)
406			}
407		})
